const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.spark}</svg>`;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateShort=day=>new Date(day+'T12:00:00Z').toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit'});
const dateFull=day=>new Date(day+'T12:00:00Z').toLocaleDateString('de-DE',{day:'2-digit',month:'long',year:'numeric'});
const percent=(a,b)=>Math.min(100,Math.round(a/Math.max(b,1)*100));
const formatTime=n=>`${Math.floor(n/60).toString().padStart(2,'0')}:${(n%60).toString().padStart(2,'0')}`;
let storage;
try{storage=window.localStorage;}catch{storage={getItem(){throw Error();},setItem(){throw Error();}};}
const loaded=loadState(storage);let state=loaded.state,storageBlocked=!!loaded.error,storageNotice=loaded.error;
let session=null,selectedWeek=1,toastTimeout,installPrompt=null;
let focus={remaining:25*60,running:false,last:Date.now(),unsaved:0};
let dfaKey='ends1',dfaWord='101',dfaPosition=0,dfaComplement=false;
let builderKey='ends1',builderHelp=false;
let builderDraft={};
const app=document.querySelector('#app');
const route=()=>location.hash.slice(1).split('/').filter(Boolean);
const progressBar=(value,purple=false)=>`<div class="progress ${purple?'purple':''}" role="progressbar" aria-label="Fortschritt" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="100"><span style="width:${value}%"></span></div>`;
function toast(message){clearTimeout(toastTimeout);const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');toastTimeout=setTimeout(()=>el.classList.remove('visible'),4500);}
function persist(){if(storageBlocked)return false;if(!saveState(state,storage)){storageNotice='Der Browser kann gerade nicht speichern. Exportiere deinen Fortschritt vor dem Schließen.';toast(storageNotice);return false;}return true;}
function announceBadges(ids){if(ids.length)toast('Pokal freigeschaltet: '+ids.map(id=>achievements.find(a=>a.id===id).title).join(' · '));}
function go(path){if(location.hash==='#'+path)render();else location.hash=path;}
const navItems=[['','home','Übersicht'],['path','book','Lernpfad'],['lab','flask','Übungslabor'],['review','repeat','Wiederholen'],['achievements','trophy','Erfolge'],['stats','chart','Statistik']];
function shell(body,active=''){
  const st=stats(state),days=Math.ceil((Date.parse(state.examDate+'T12:00:00Z')-Date.parse(today()+'T12:00:00Z'))/86400000);
  const label=navItems.find(n=>n[0]===active)?.[2]||'Dein Lernraum';
  return `<div class="shell"><aside class="sidebar"><a class="brand" href="#"><img src="./assets/icon.svg" alt="">orbit<span class="lime">.</span></a><div class="brand-sub">DEIN LERNUNIVERSUM</div><div class="nav-label">DEIN LERNRAUM</div><nav class="nav" aria-label="Hauptnavigation">${navItems.map(([id,i,name])=>`<a href="#${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(i)}${name}${id==='review'&&st.due?`<span class="nav-badge">${st.due}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="exam-side"><span class="pill purple">${icon('flag')} DEIN ZIEL</span><p>Klausur Theoretische Informatik</p><strong>${dateFull(state.examDate)}</strong>${progressBar(percent(st.completed,lessons.length),true)}<small class="muted">${st.completed}/${lessons.length} Lektionen · Woche 1</small></div><div class="profile"><div class="avatar">DU</div><span>Dein Lernraum<small>Level ${1+Math.floor(st.xp/150)} · ${st.xp} XP</small></span><a href="#settings" class="icon-btn" aria-label="Einstellungen">${icon('settings')}</a></div></div></aside><div class="main"><header class="topbar"><a class="brand mobile-brand" href="#"><img src="./assets/icon.svg" alt="">orbit.</a><div class="breadcrumb">Dein Lernraum <span aria-hidden="true"> / </span> <strong>${label}</strong></div><div class="top-actions"><span class="top-pill">${icon('flame')} <strong>${st.streak}</strong> ${st.streak===1?'Lerntag':'Lerntage'}</span><span class="top-divider"></span><span class="top-pill">${icon('calendar')} ${days>0?`${days} Tage bis zum Ziel`:days===0?'Heute ist dein Zieltag':'Zieltermin erreicht'}</span><a href="#settings" class="avatar" aria-label="Einstellungen öffnen">DU</a></div></header><main class="content content-enter" id="content" tabindex="-1">${storageNotice?`<div class="notice">${esc(storageNotice)} <a href="#settings">Speicher verwalten →</a></div>`:''}${body}<footer class="footer"><span>${icon('shield')} Dein Fortschritt bleibt auf diesem Gerät.</span><a href="#settings">Quellen, Datensicherung & Einstellungen ${icon('chevron')}</a></footer></main></div><nav class="mobile-nav" aria-label="Mobile Navigation">${[['','home','Start'],['path','book','Lernpfad'],['lab','flask','Labor'],['review','repeat','Üben'],['achievements','trophy','Erfolge']].map(([id,i,n])=>`<a href="#${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(i)}${n}</a>`).join('')}</nav></div>`;
}
function pageHead(eyebrow,title,description,extra=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>${extra}</div>`;}
function nextLesson(){return lessons.find(l=>!state.completed[l.id])||lessonById[state.lastLesson]||lessons[0];}
function dashboard(){
  const st=stats(state),next=nextLesson(),doneToday=state.activity[today()]?.unique.length||0;
  const orderedLessons=[next,...lessons.filter(l=>l.id!==next.id&&!state.completed[l.id])].slice(0,3);
  const weekStart=addDays(today(),-(new Date(today()+'T12:00:00Z').getUTCDay()+6)%7);
  return shell(`${pageHead('DEIN CAMPUS FÜR THEORETISCHE INFORMATIK','Ein guter Tag, um weiterzukommen.','Dein Ziel ist Verständnis. Dein Weg beginnt mit dem nächsten kleinen Schritt.',`<span class="pill gray"><span class="dot"></span> Woche 01 / 09</span>`)}<div class="grid dashboard-grid"><div class="stack"><section class="card hero"><div class="hero-copy"><span class="pill">WOCHE 01 · DAS FUNDAMENT</span><div class="eyebrow">VERSTEHEN. AUSPROBIEREN. ANWENDEN.</div><h2>Kleine Schritte.<br>Großes Verständnis.</h2><p>Von deinem ersten Wort zum eigenen Automaten. Entdecke die Bausteine der theoretischen Informatik.</p><a href="#lesson/${next.id}" class="btn dark">${st.completed?'Weiterlernen':'Lernreise starten'} ${icon('arrow')}</a></div><div class="hero-art" aria-hidden="true"><div class="orb"></div><div class="orb o2"></div><div class="orb o3"></div><div class="core">Σ*</div><span class="floating f1">ε</span><span class="floating f2">q₁</span><span class="floating f3">{0,1}</span><span class="orb-dot"></span></div></section><div class="mini-stats"><div class="mini-stat">${icon('spark')}<div><strong>${st.xp}<small> XP</small></strong><span>Wissen gesammelt</span></div></div><div class="mini-stat">${icon('book')}<div><strong>${st.completed}<small> / 19</small></strong><span>Lektionen geschafft</span></div></div><a href="#review" class="mini-stat">${icon('repeat')}<div><strong>${st.due}</strong><span>Wiederholungen fällig</span></div></a></div><section><div class="section-heading"><h2>Dein nächster Schritt</h2><a href="#path">Zum Lernpfad ${icon('chevron')}</a></div><div class="card">${orderedLessons.map((l,i)=>`<a class="lesson-row" href="#lesson/${l.id}"><span class="lesson-num ${i===0?'current':''}">${String(lessons.indexOf(l)+1).padStart(2,'0')}</span><div><h3>${l.title}</h3><p>${l.minutes} Min. · Erklärung, Beispiel & Übungen</p></div><span class="go">${icon(i===0?'play':'chevron')}</span></a>`).join('')}</div></section><div class="grid two-cards"><a href="#lab" class="card action-card">${icon('flask')}<div><h3>Wissen wird lebendig</h3><p>Experimentiere in fünf Lernlaboren.</p></div><span class="go">${icon('arrow')}</span></a><a href="#check" class="card action-card">${icon('target')}<div><h3>Bereit für den Wochencheck?</h3><p>10 Fragen. Zwei eigene Automaten.</p></div><span class="go">${icon('arrow')}</span></a></div></div><aside class="stack"><section class="card goal-card"><div class="card-title"><h2>Dein Tagesziel</h2><a href="#settings" aria-label="Tagesziel anpassen">${icon('settings')}</a></div><div class="ring" style="--amount:${percent(doneToday,state.goal)}"><div class="ring-inner"><strong>${doneToday}<span> / ${state.goal}</span></strong><small>Aufgaben gelöst</small></div></div><p>${doneToday>=state.goal?'Ziel erreicht. Ein guter Moment für eine Pause.':`${Math.max(0,state.goal-doneToday)} neue richtige Antworten bis zu deinem Ziel.`}</p><button class="btn full" data-action="daily">${doneToday>=state.goal?'Eine weitere Runde':'Tagesrunde starten'} ${icon('arrow')}</button><div class="week-dots">${['M','D','M','D','F','S','S'].map((d,i)=>{const day=addDays(weekStart,i);return `<div class="week-dot ${state.activity[day]?'done':''} ${day===today()?'today':''}"><span>${state.activity[day]?'✓':'·'}</span>${d}</div>`;}).join('')}</div></section><section class="card focus-card"><div class="card-title"><h2>Raum für Fokus</h2>${icon('clock')}</div><div class="timer" id="focus-timer">${formatTime(focus.remaining)}</div><p>25 Minuten nur für dich und den Stoff.</p><div class="focus-controls"><button class="btn secondary" data-action="focus" id="focus-toggle">${icon(focus.running?'pause':'play')}${focus.running?'Pausieren':'Fokus starten'}</button><button class="icon-btn" data-action="focus-reset" aria-label="Fokuszeit zurücksetzen">${icon('repeat')}</button></div><p class="tiny" style="margin-top:12px">${focus.running?'Läuft, solange die App im Vordergrund ist.':'Der Timer zählt nur bei sichtbarer App.'}</p></section><a href="#achievements" class="card trophy-preview"><span class="trophy-icon">${icon('trophy')}</span><div><h3>Jeder Schritt zählt.</h3><p>${state.badges.length} von ${achievements.length} Pokalen freigeschaltet.</p></div></a></aside></div>`);
}
function pathPage(){const w=weeks[selectedWeek-1],st=stats(state);return shell(`${pageHead('DEINE ROUTE BIS ZUR KLAUSUR','Dein Lernpfad','Neun Wochen, ein klares Ziel. Du bestimmst das Tempo.')}<div class="week-tabs" role="group" aria-label="Lernwoche auswählen">${weeks.map(w=>`<button data-action="week" data-week="${w.n}" class="${w.n===selectedWeek?'active':''}" aria-pressed="${w.n===selectedWeek}">Woche ${String(w.n).padStart(2,'0')}${w.n>1?' · Plan':''}</button>`).join('')}</div><section class="card week-intro"><div><span class="pill ${w.n===1?'':'gray'}">${w.n===1?'INTERAKTIV VERFÜGBAR':'GEPLANT · NOCH KEINE INTERAKTIVEN LEKTIONEN'}</span><h2 style="margin-top:15px">${w.title}</h2><p>${w.subtitle}</p><div class="week-meta"><span>${dateShort(w.start)} – ${dateShort(w.end)}2026</span><span>ca. ${w.hours} Stunden</span><span>${w.n===1?`${st.completed}/19 Lektionen abgeschlossen`:'Lernziel aus deinem Masterplan'}</span></div></div><span class="week-number" aria-hidden="true">${String(w.n).padStart(2,'0')}</span></section>${w.n===1?`${units.map((u,index)=>`<section class="card unit"><div class="unit-head">${icon(u.icon)}<div><h2>${String(index+1).padStart(2,'0')} · ${u.title}</h2><p>${u.subtitle}</p></div><span class="pill gray">${u.lessons.filter(id=>state.completed[id]).length}/${u.lessons.length}</span></div><div class="lesson-grid">${u.lessons.map(id=>{const l=lessonById[id],m=mastery(state,id);return `<a href="#lesson/${id}" class="lesson-tile"><span class="lesson-num ${state.completed[id]?'current':''}">${state.completed[id]?icon('check'):String(lessons.indexOf(l)+1).padStart(2,'0')}</span><div><h3>${l.title}</h3><p><span class="state-dot ${m}"></span>${m==='safe'?'Sicher':m==='learning'?'Im Aufbau':'Noch offen'} · ${l.minutes} Min. Einstieg</p></div></a>`;}).join('')}</div></section>`).join('')}<section class="card"><div class="card-title"><h2>Dein Wochenabschluss</h2>${icon('flag')}</div><p class="small muted">${w.goal} Für die Übungen und handschriftlichen Lösungswege sind weitere Arbeitsblöcke vorgesehen.</p><div class="inline-actions" style="margin-top:20px"><a href="#check" class="btn">Wochencheck öffnen ${icon('arrow')}</a><a href="#stats" class="btn ghost">Kompetenzen ansehen</a></div></section>`:`<section class="card planned"><div class="card-title"><h2>Das ist für Woche ${w.n} vorgesehen</h2>${icon('calendar')}</div><ol class="next-week-list">${w.topics.map(t=>`<li>${t}</li>`).join('')}</ol><div class="separator"></div><p class="small"><strong>Deine Aufgaben:</strong> ${w.tasks}</p><p class="small muted"><strong>Nachweis am Wochenende:</strong> ${w.goal}</p><div class="callout" style="margin-top:22px"><strong>Der Kalender steht, die Lektionen folgen.</strong>Diese Woche ist als Planung aus dem Masterplan hinterlegt. In dieser Version ist Woche 1 vollständig interaktiv. Die späteren Wochen werden nicht als bereits bearbeitbarer Stoff dargestellt.</div><a href="#path" class="btn secondary" style="margin-top:20px" data-action="week" data-week="1">Zur interaktiven Woche 1 ${icon('arrow')}</a></section>`}<p class="help" style="margin-top:20px">„Abgeschlossen“: mindestens 80 % der Lektionsaufgaben ohne Hinweis. „Sicher“: zwei unterschiedliche Aufgaben an unterschiedlichen Tagen ohne Hilfe, ohne offene Fehler. Prozentziele sind eigene Trainingsziele.</p>`,'path');}
function lessonPage(id){const l=lessonById[id];if(!l)return notFound();state.lastLesson=id;persist();const qs=questions.filter(q=>q.lesson===id);return shell(`<a href="#path" class="back-link">${icon('back')} Zurück zum Lernpfad</a><div class="reading-layout"><article class="reading"><div class="eyebrow">WOCHE 1 · LEKTION ${String(lessons.indexOf(l)+1).padStart(2,'0')}</div><h1>${l.title}</h1><p class="lead">${l.intro}</p>${l.sections.map(([t,p])=>`<section class="reading-section"><h2>${t}</h2><p>${esc(p)}</p></section>`).join('')}<div class="example"><h3>${icon('spark')} ${l.example[0]}</h3><p>${esc(l.example[1])}</p></div><div class="callout"><strong>Genau hinschauen</strong>${esc(l.trap)}</div><section class="reading-section"><h2>Jetzt in deinen Worten</h2><p>${esc(l.reflection)}</p><label class="field" style="margin-top:16px"><span>Deine Erklärung (private Notiz, keine automatische Bewertung)</span><textarea id="lesson-note" maxlength="4000" placeholder="Wie würdest du es jemandem erklären?">${esc(state.notes[id]||'')}</textarea></label><button class="btn ghost" data-action="save-note" data-id="${id}">Notiz speichern</button><div class="note-status" id="note-status" role="status"></div></section><div class="reading-footer"><button class="btn" data-action="lesson-quiz" data-id="${id}">Wissen anwenden · ${qs.length} Aufgaben ${icon('arrow')}</button>${l.lab?`<a href="#lab/${l.lab}" class="btn secondary">Im Labor ausprobieren ${icon('flask')}</a>`:''}</div></article><aside class="card sticky"><div class="eyebrow">DEINE LERNSCHLEIFE</div><h3>Verstehen wird Können.</h3><div class="separator"></div><p class="muted">01 · Erklärung lesen<br><br>02 · Beispiel nachvollziehen<br><br>03 · Selbst rechnen und begründen<br><br>04 · Ohne Vorlage überprüfen</p><div class="separator"></div><p class="help">${l.source}<br>Ca. ${l.minutes} Minuten für Erklärung und ersten Check. Rechenübungen kommen zusätzlich dazu.</p>${state.completed[id]?`<p class="completed-stamp" style="margin-top:18px">✓ Lektion abgeschlossen</p>`:''}</aside></div>`,'path');}
function reviewPage(){const due=dueQuestions(state),errors=Object.entries(state.errors).filter(([,e])=>!e.resolved);return shell(`${pageHead('WISSEN, DAS BLEIBT','Wiederholen mit Richtung.','Fehler zeigen dir, was als Nächstes hilfreich ist.')}<div class="grid two-cards"><section class="card"><div class="card-title"><h2>Heute fällig</h2>${icon('repeat')}</div><div class="score">${due.length}</div><p class="small muted">Wiederholungen nach 1, 3, 7 und 14 Tagen. Falsche oder mit Hinweis gelöste Aufgaben kommen sofort zurück.</p><button class="btn" data-action="review" style="margin-top:22px" ${due.length?'':'disabled'}>Fällige Aufgaben üben ${icon('arrow')}</button></section><section class="card"><div class="card-title"><h2>Eine kleine Tagesrunde</h2>${icon('spark')}</div><p class="small muted">Ein Mix aus passenden Grundlagen und deinen nächsten Lernschritten. Öffne bei neuen Begriffen zuerst die zugehörige Lektion.</p><button class="btn secondary" data-action="daily" style="margin-top:22px">5 Aufgaben starten ${icon('arrow')}</button><p class="help" style="margin-top:20px">Richtige Antworten nach eingeblendeten Hinweisen zählen als Übung, nicht als selbstständiger Nachweis.</p></section></div><div class="section-heading" style="margin-top:30px"><h2>Dein Fehlerprotokoll</h2><span class="pill gray">${errors.length} offen</span></div>${errors.length?errors.map(([id,e])=>{const q=questionById[id];return `<section class="card error-card"><div class="eyebrow">${lessonById[q.lesson].title} · ${dateShort(e.date)}</div><h3>${esc(q.prompt)}</h3><details><summary>Richtige Regel und Erklärung ansehen</summary><div class="feedback info">${esc(q.explanation)}</div></details><div class="grid two-cards"><label class="field">Was war deine Fehlerursache?<textarea maxlength="4000" id="error-note-${id}" placeholder="Zum Beispiel: ε übersehen …">${esc(e.note)}</textarea></label><label class="field">Meine Regel für das nächste Mal<textarea maxlength="4000" id="error-rule-${id}" placeholder="Worauf achtest du künftig?">${esc(e.rule)}</textarea></label></div><div class="inline-actions"><button class="btn ghost" data-action="save-error" data-id="${id}">Notiz speichern</button><button class="btn secondary" data-action="retry-question" data-id="${id}">Erneut versuchen ${icon('arrow')}</button><a href="#lesson/${q.lesson}" class="small muted">Erklärung lesen</a></div></section>`;}).join(''):`<section class="card empty-state">${icon('check')}<h2>Raum für neue Erkenntnisse.</h2><p>Du hast gerade keine offenen Fehler. Sobald etwas noch nicht sitzt, findest du hier die Aufgabe, die Erklärung und Platz für deine eigene Regel.</p><a href="#path" class="btn secondary">Weiter zum Lernpfad</a></section>`}`,'review');}
function achievementPage(){const st=stats(state);return shell(`${pageHead('DEINE KLEINEN UND GROSSEN ERFOLGE','Das hast du dir erarbeitet.','Pokale für echtes Üben, Wiederholen und Anwenden.',`<span class="pill purple">${state.badges.length} / ${achievements.length} freigeschaltet</span>`)}<div class="card" style="margin-bottom:25px"><div class="card-title"><h2>Level ${1+Math.floor(st.xp/150)} · ${st.xp} Erfahrungspunkte</h2>${icon('spark')}</div>${progressBar(percent(st.xp%150,150))}<p class="help">${150-st.xp%150} XP bis zum nächsten Level. 10 XP je erstmals ohne Hilfe gelöster Aufgabe, 25 je abgeschlossener Lektion, 50 je eigener Automatenkonstruktion. Fällige Wiederholungen: 5 XP, höchstens einmal pro Aufgabe und Tag.</p></div><div class="grid achievement-grid">${achievements.map(a=>{const unlocked=state.badges.includes(a.id);return `<section class="card achievement ${unlocked?'unlocked':'locked'}"><span class="lock">${icon(unlocked?'check':'lock')}</span><div class="achievement-icon">${icon(a.icon)}</div><h3>${a.title}</h3><p>${a.description}</p>${unlocked?'<span class="pill" style="margin-top:17px">GESCHAFFT</span>':''}</section>`;}).join('')}</div>`,'achievements');}
function statsPage(){const st=stats(state);return shell(`${pageHead('DEIN LERNEN AUF EINEN BLICK','Fortschritt, der etwas bedeutet.','Deine eigenen Daten – ohne erfundene Ergebnisse oder Ranglisten.')}<div class="stats-grid">${[['target',st.attempts?st.accuracy+' %':'—','Richtige Antworten · alle Versuche'],['book',st.completed+'/19','Lektionen abgeschlossen'],['flame',st.streak,'Aktuelle Lernserie · Tage'],['clock',Math.floor(state.focusSeconds/60)+' Min.','Aktive Fokuszeit']].map(([i,v,t])=>`<div class="card stat-big">${icon(i)}<strong>${v}</strong><p>${t}</p></div>`).join('')}</div><div class="grid two-cards"><section class="card"><div class="card-title"><h2>Deine letzten 42 Tage</h2>${icon('calendar')}</div><p class="help">${st.attempts} Antworten insgesamt · ${st.unique} verschiedene Aufgaben ohne Hilfe gelöst.</p><div class="heatmap" role="img" aria-label="Lernaktivität der letzten 42 Tage">${Array.from({length:42},(_,i)=>{const d=addDays(today(),i-41),v=state.activity[d]?.attempts||0;return `<div class="heat" data-level="${v>=10?3:v>=5?2:v>0?1:0}" title="${dateFull(d)}: ${v} Antworten" aria-label="${dateFull(d)}: ${v} Antworten"></div>`;}).join('')}</div><div class="legend">Weniger ${[0,1,2,3].map(i=>`<span class="heat" data-level="${i}"></span>`).join('')} Mehr</div><a href="#achievements" class="btn ghost" style="margin-top:24px">Deine Erfolge ansehen ${icon('arrow')}</a></section><section class="card"><div class="card-title"><h2>Kompetenzen aufbauen</h2><span class="pill">${st.safe} sicher</span></div>${units.map(u=>{const completed=u.lessons.filter(id=>state.completed[id]).length,safe=u.lessons.filter(id=>mastery(state,id)==='safe').length;return `<div class="topic-bar"><div class="labels"><span>${u.title}</span><span>${completed}/${u.lessons.length}</span></div>${progressBar(percent(completed,u.lessons.length),true)}<p class="tiny muted">${safe} sicher · ${completed} abgeschlossen</p></div>`;}).join('')}<p class="help" style="margin-top:20px">Sicher = unterschiedliche Aufgaben an unterschiedlichen Tagen ohne Hilfe; offene Fehler setzen den Status zurück.</p></section></div><section class="card" style="margin-top:23px"><div class="card-title"><h2>Deine Wochenchecks</h2><a href="#check">Check starten →</a></div>${state.checks.length?`<div class="table-scroll"><table><thead><tr><th>Datum</th><th>Ergebnis</th><th>Bearbeitungszeit</th></tr></thead><tbody>${state.checks.slice(-10).reverse().map(c=>`<tr><td>${dateFull(c.date)}</td><td>${c.score}/10</td><td>${formatTime(c.seconds)}</td></tr>`).join('')}</tbody></table></div><p class="help">Wiederholungen derselben Checkfragen zeigen Routine. Für einen unabhängigen Leistungsnachweis brauchst du neue Aufgaben.</p>`:'<p class="small muted">Noch kein Wochencheck abgeschlossen. Beginne mit den Erklärungen und probiere anschließend den Check ohne Vorlage.</p>'}</section>`,'stats');}
function checkPage(){const best=Math.max(0,...state.checks.map(c=>c.score));return shell(`${pageHead('WOCHE 1 · DEIN PERSÖNLICHER NACHWEIS','Was bleibt ohne Vorlage?','Kein Zeitdruck. Zeig dir selbst, welche Grundlagen schon sitzen.')}<section class="card"><div class="check-summary"><div><strong>10</strong> Anwendungsfragen</div><div><strong>8/10</strong> Persönliches Trainingsziel</div><div><strong>2</strong> Eigene Automaten</div></div><p class="small muted">Die Aufgaben prüfen den Stoff deines Wochenchecks. Lösungen und Erklärungen erscheinen erst am Ende. Leg das Skript zur Seite und notiere deine Begründungen zusätzlich auf Papier. Die App bewertet die prüfbaren Antworten; deine Begründungen vergleichst du selbst mit den Erläuterungen.</p><button class="btn" data-action="weekly-check" style="margin-top:25px">Wochencheck starten ${icon('arrow')}</button>${state.checks.length?`<p class="help" style="margin-top:16px">Bisheriger Bestwert: ${best}/10. ${state.checks.length} Durchläufe.</p>`:''}</section><section class="card" style="margin-top:24px"><h2>Der praktische Teil</h2><p class="small muted" style="margin-top:12px">Erstelle die Übergänge und Endzustände ohne Vorlage. Beide Automaten werden vollständig auf Sprachgleichheit geprüft. Zustandsnamen sind für die Aufgabe vorgegeben.</p>${[['ends1','Binärwörter, die auf 1 enden'],['alternate','Binärwörter ohne gleiche Nachbarn']].map(([id,t])=>`<div class="lesson-row"><span class="lesson-num ${state.builders[id]?'current':''}">${icon(state.builders[id]?'check':'nodes')}</span><div><h3>${t}</h3><p>${state.builders[id]?'Ohne Vorlage konstruiert':'Noch offen · eigene Konstruktion'}</p></div><button class="btn secondary" style="margin-left:auto" data-action="open-builder" data-id="${id}">Bauen</button></div>`).join('')}<p class="help" style="margin-top:22px">Der Wochenpokal wird erst bei mindestens 8/10 und beiden erfolgreich gebauten Pflichtautomaten freigeschaltet. Das ist ein Trainingsziel, keine offizielle Notengrenze.</p></section>`,'path');}
function settingsPage(){return shell(`${pageHead('DEIN LERNRAUM, DEINE EINSTELLUNGEN','So passt Orbit zu dir.','Lernziel, Sicherung und die Grundlagen dieser App.')}<div class="settings-grid"><section class="card"><h2>Deine Ziele</h2><label class="field">Tagesziel<select id="goal">${[5,10,15].map(n=>`<option value="${n}" ${state.goal===n?'selected':''}>${n} verschiedene richtige Aufgaben</option>`).join('')}</select></label><label class="field">Dein Klausurtermin<input id="exam-date" type="date" value="${state.examDate}" min="2020-01-01" max="2100-12-31"></label><button class="btn" data-action="save-settings">Ziele speichern</button><p class="help" style="margin-top:15px">Der Wochenplan bleibt an den Originaldaten 21.09.–20.11.2026 ausgerichtet. Ein geänderter Klausurtermin passt den Countdown an.</p></section><section class="card"><h2>Vom PC aufs Handy</h2><p>Der Lernstand wird nur in diesem Browser gespeichert. Es gibt kein Konto und keine automatische Synchronisierung. Exportiere ihn auf einem Gerät und importiere die Datei auf dem anderen.</p><button class="btn secondary" data-action="export">${icon('download')} Fortschritt exportieren</button><button class="btn ghost" data-action="import">Sicherung importieren</button><input type="file" class="file-input" id="import-file" accept="application/json,.json"><p class="help" style="margin-top:17px">Beim Import prüfst du erst die Zusammenfassung. Nach deiner Bestätigung ersetzt die Sicherung den aktuellen Stand. Beim Löschen von Browserdaten geht der lokale Stand verloren.</p><div id="import-preview" role="status"></div></section><section class="card"><h2>Deine App auf dem Startbildschirm</h2><p>iPhone: In Safari öffnen → Teilen → „Zum Home-Bildschirm“. Android: Im Browsermenü „App installieren“ oder „Zum Startbildschirm hinzufügen“.</p>${installPrompt?'<button class="btn" data-action="install">Orbit installieren</button>':''}<p class="help">Nach dem ersten vollständigen Laden funktioniert das Lernmaterial auch offline. Für die erste Nutzung und Updates benötigst du eine Verbindung. Fortschrittsexport bleibt weiterhin wichtig.</p><div class="separator"></div><a href="#stats" class="btn secondary">${icon('chart')} Statistik öffnen</a></section><section class="card"><h2>Woher kommen die Inhalte?</h2><p>Woche 1 wurde aus deinem 42-seitigen Lernskript neu als interaktives Training aufgebaut. Der Neun-Wochen-Pfad folgt deinem Masterplan.</p><ul class="source-list"><li>Lernskript Woche 1: Grundlagen, Beispiele und Korrekturen, S. 3–41.</li><li>Masterplan zur Klausur am 20.11.2026: Wochen, Ziele und Wiederholungen, S. 2–8.</li><li>Aufgaben 1–4 und die im Skript benannten Vorlesungsstellen.</li></ul><p class="help">Original-PDFs sind nicht Bestandteil der öffentlichen App. Bei Lektionen stehen genaue Fundstellen. Die weiteren Wochen sind geplant; noch nicht als interaktive Lektionen verfügbar. Prüfungsdauer und Hilfsmittel sind hier nicht als bestätigt hinterlegt.</p></section><section class="card"><h2>Speicher verwalten</h2><p>Ein Neustart löscht nur deinen lokalen Orbit-Lernstand. Exportiere vorher eine Sicherung, wenn du ihn behalten möchtest.</p>${storageBlocked?'<button class="btn secondary" data-action="recover">Nach Sicherung neu speichern</button>':''}<button class="btn danger" data-action="reset">Lernstand zurücksetzen</button></section><section class="card"><h2>Dein Wochenrhythmus</h2><p>Mo, Di, Do, Fr jeweils 75 Minuten; Sa zweimal 75 Minuten; So 30 Minuten. Mittwoch ist frei oder Puffer.</p><p class="help">Eine Standard-Einheit: 10 Minuten abrufen, 15 verstehen, 40 selbst rechnen, 10 korrigieren. Die kurzen App-Lektionen ergänzen deine handschriftlichen Aufgaben. App-Nutzung allein bestätigt noch keine Klausurreife.</p><a href="https://github.com/76patrik/quiet-orbit-lab" target="_blank" rel="noreferrer" class="small lime">Quellcode auf GitHub ↗</a></section></div>`,'settings');}
function notFound(){return shell('<section class="card empty-state"><h1>Hier ist noch kein Lernpfad.</h1><p>Diese Seite gibt es nicht.</p><a href="#path" class="btn">Zum Lernpfad</a></section>');}

function render(){
  const [page='',id]=route();
  const pages={'':dashboard,path:pathPage,lesson:()=>lessonPage(id),review:reviewPage,achievements:achievementPage,stats:statsPage,settings:settingsPage,check:checkPage,quiz:quizPage,lab:()=>labPage(id||'sets')};
  app.innerHTML=(pages[page]||notFound)();
  document.title=`${page==='lesson'&&lessonById[id]?lessonById[id].title:({path:'Lernpfad',review:'Wiederholen',stats:'Statistik',achievements:'Erfolge',settings:'Einstellungen',check:'Wochencheck',quiz:'Training',lab:'Übungslabor'}[page]||'Dein Lernraum')} · Orbit`;
  if(page==='lab'&&id==='dfa')renderDfaStage();
  if(page==='lab'&&id==='complexity')renderGrowth();
}

const shuffled=values=>{const out=[...values];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]];}return out;};
function startSession(items,{type='practice',title='Eine Runde für dein Wissen',lesson=null}={}){
  session={items:[...items],index:0,type,title,lesson,selected:null,input:'',hint:false,feedback:null,answers:[],finished:false,started:Date.now(),seconds:0,options:{}};
  for(const q of items)if(q.options)session.options[q.id]=shuffled(q.options.map((text,index)=>({text,index})));
  if(!items.length){toast('Gerade sind keine Aufgaben fällig.');return;}
  go('quiz');
}
function dailySession(){
  const eligible=new Set([...Object.keys(state.completed),state.lastLesson,nextLesson().id].filter(Boolean));
  const pool=questions.filter(q=>eligible.has(q.lesson));
  const fresh=shuffled(pool.filter(q=>!state.results[q.id]?.successes.length));
  const others=shuffled(pool.filter(q=>!fresh.some(f=>f.id===q.id)));
  startSession([...fresh,...others].slice(0,5),{title:'Deine Tagesrunde'});
}
function answerLabel(q){return q.type==='choice'?q.options[q.answer]:q.type==='set'?setLabel(q.answer):String(q.answer);}
function quizPage(){
  if(!session)return shell(`<section class="card empty-state">${icon('book')}<h2>Bereit für eine neue Runde?</h2><p>Ein laufender Durchgang bleibt nur bis zum Neuladen erhalten. Bereits gespeicherte Antworten findest du weiterhin in deiner Statistik.</p><button class="btn" data-action="daily">Tagesrunde starten</button></section>`,'review');
  if(session.finished)return resultPage();
  const q=session.items[session.index],f=session.feedback,isCheck=session.type==='check';
  return shell(`<div class="quiz"><div class="quiz-top"><a href="${session.lesson?'#lesson/'+session.lesson:'#review'}" class="back-link" style="margin:0">${icon('back')} ${session.lesson?'Zur Lektion':'Training verlassen'}</a><span>${session.index+1} / ${session.items.length}</span></div>${progressBar(percent(session.index,session.items.length),true)}<section class="card quiz-card" style="margin-top:22px"><div class="eyebrow">${esc(session.title)} · ${q.type==='choice'?'Eine Antwort wählen':q.type==='set'?'Eine Menge selbst berechnen':q.type==='regex'?'RegEx selbst konstruieren':'Selbst berechnen'}</div><h1 id="question-title">${esc(q.prompt)}</h1>${q.type==='choice'?`<div class="answers" role="group" aria-labelledby="question-title">${session.options[q.id].map(({text,index},i)=>`<button class="answer ${session.selected===index?'selected':''} ${f&&index===q.answer?'correct':''} ${f&&session.selected===index&&!f.correct?'wrong':''}" data-action="select-answer" data-index="${index}" aria-pressed="${session.selected===index}" ${f?'disabled':''}><span class="answer-letter">${String.fromCharCode(65+i)}</span>${esc(text)}</button>`).join('')}</div>`:`<label class="field"><span>Deine Antwort</span><input id="quiz-input" value="${esc(session.input)}" ${q.type==='number'?'inputmode="numeric"':''} autocomplete="off" spellcheck="false" maxlength="${q.type==='regex'?120:1000}" placeholder="${q.type==='set'?'Zum Beispiel: {ε, 0, 01} oder ∅':q.type==='regex'?'Zum Beispiel: (0|1)*':'Dein Ergebnis'}" ${f?'disabled':''}></label>${q.type==='set'||q.type==='regex'?symbolKeyboard('quiz-input',q.type==='regex'?['ε','∅','∪','(',')','*','+']:['ε','∅','{','}',',']):''}<p class="help">${q.type==='set'?'Reihenfolge und doppelte Einträge ändern eine Menge nicht. ε, eps oder epsilon stehen für das leere Wort.':q.type==='regex'?'Gleichwertige Ausdrücke sind erlaubt. Die App prüft die vollständige Sprache.':''}</p>`}${session.hint?`<div class="feedback info"><strong>Ein kleiner Hinweis</strong>${esc(q.hint)}<br><small>Diese Antwort zählt nicht als Nachweis ohne Hilfe.</small></div>`:''}<div id="quiz-error" role="status"></div>${f?`<div class="feedback ${f.correct?'':'error'}" role="status"><strong>${f.correct?session.hint?'Richtig mit Unterstützung.':'Richtig. Das passt!':'Hier steckt dein nächster Lernschritt.'}</strong>${esc(q.explanation)}${f.counter?`<p>${esc(f.counter)}</p>`:''}${!f.correct?`<p><strong>Eine richtige Antwort: ${esc(answerLabel(q))}</strong></p>`:''}</div>`:''}<div class="quiz-controls">${f?`<a class="small muted" href="#lesson/${q.lesson}">Erklärung nachlesen</a><button class="btn" data-action="next-question">${session.index+1===session.items.length?'Runde abschließen':'Nächste Aufgabe'} ${icon('arrow')}</button>`:`<div class="inline-actions">${!isCheck?`<button class="btn ghost" data-action="hint" ${session.hint?'disabled':''}>Hinweis</button>`:''}<button class="btn ghost" data-action="skip">Weiß ich noch nicht</button></div><button class="btn" data-action="submit-answer">${isCheck?'Antwort festhalten':'Antwort prüfen'} ${icon('arrow')}</button>`}</div>${isCheck?'<p class="help" style="margin-top:20px">Im Wochencheck werden Lösungen und Bewertung erst am Ende angezeigt.</p>':''}</section></div>`,'review');
}
function submitAnswer(skip=false){
  if(!session||session.finished||session.feedback)return;
  const q=session.items[session.index];let value=q.type==='choice'?session.selected:document.querySelector('#quiz-input')?.value;
  if(q.type!=='choice')session.input=value||'';
  if(!skip&&(value===null||value===undefined||String(value).trim()==='')){document.querySelector('#quiz-error').innerHTML='<div class="feedback error">Wähle oder gib zuerst eine Antwort ein.</div>';return;}
  let correct=false,counter='';
  try{if(!skip){correct=grade(q,value);if(q.type==='regex'&&!correct){const test=compareRegex(value,q.answer);counter=`Gegenbeispiel: ${wordLabel(test.word)} wird von deinem Ausdruck ${test.actual?'angenommen':'abgelehnt'}, müsste aber ${test.expected?'angenommen':'abgelehnt'} werden.`;}}}
  catch(e){document.querySelector('#quiz-error').innerHTML=`<div class="feedback error">${esc(e.message)}</div>`;return;}
  const answer={qid:q.id,correct,assisted:session.hint,value:skip?'':value,counter};
  session.answers.push(answer);
  if(session.type==='check'){nextQuestion();return;}
  announceBadges(recordAnswer(state,q.id,correct,{assisted:session.hint,review:session.type==='review'}));persist();session.feedback={correct,counter};render();
}
function nextQuestion(){
  if(session.index+1>=session.items.length){finishSession();return;}
  session.index++;session.selected=null;session.input='';session.hint=false;session.feedback=null;render();window.scrollTo({top:0,behavior:'instant'});
}
function finishSession(){
  if(session.finished)return;session.finished=true;session.seconds=Math.min(86400,Math.round((Date.now()-session.started)/1000));
  const earned=session.answers.filter(a=>a.correct&&!a.assisted).length;const newBadges=[];
  if(session.type==='check'){
    for(const a of session.answers)newBadges.push(...recordAnswer(state,a.qid,a.correct));
    state.checks.push({date:today(),score:earned,seconds:session.seconds});newBadges.push(...updateBadges(state));
  }
  if(session.lesson&&earned/session.items.length>=.8)newBadges.push(...completeLesson(state,session.lesson));
  announceBadges([...new Set(newBadges)]);persist();render();window.scrollTo({top:0,behavior:'instant'});
}
function resultPage(){
  const earned=session.answers.filter(a=>a.correct&&!a.assisted).length,passed=earned/session.items.length>=.8;
  const wrong=session.answers.filter(a=>!a.correct||a.assisted);
  return shell(`<div class="quiz"><section class="card quiz-result"><div class="result-symbol">${icon(passed?'trophy':'spark')}</div><div class="eyebrow">${esc(session.title)} · GESCHAFFT</div><h1>${passed?'Ein guter Schritt nach vorn.':'Du weißt jetzt, wo es weitergeht.'}</h1><div class="score">${earned}<span> / ${session.items.length}</span></div><p class="muted small">Ohne Hilfe richtig · ${formatTime(session.seconds)} Bearbeitungszeit</p><p class="small muted" style="margin-top:18px">${session.lesson?passed?'Die Lektion ist abgeschlossen. Wiederhole sie später mit einer anderen Aufgabe, um sie sicher zu festigen.':'Die Lektion bleibt offen. Schau dir die Fehler an und probiere den Lektionscheck erneut.':session.type==='check'?passed?'Das Fragenziel ist erreicht. Für den Wochenpokal gehören noch die beiden eigenen Automaten dazu.':'Dein Ziel sind mindestens 8 von 10 Fragen. Nimm dir zuerst die unten aufgeführten Themen vor.':'Dein Fortschritt und deine Wiederholungstermine sind gespeichert.'}</p><div class="result-actions">${session.lesson?`<button class="btn" data-action="lesson-quiz" data-id="${session.lesson}">${passed?'Lektion erneut üben':'Lektionscheck wiederholen'}</button><a href="#path" class="btn secondary">Zum Lernpfad</a>`:session.type==='check'?'<a href="#check" class="btn">Zum praktischen Teil</a><a href="#review" class="btn secondary">Fehler nacharbeiten</a>':'<a href="#path" class="btn">Weiterlernen</a><a href="#stats" class="btn secondary">Statistik ansehen</a>'}</div></section>${session.answers.map(a=>{const q=questionById[a.qid];return `<section class="card error-card"><div class="eyebrow">${a.correct?'RICHTIG':'NOCH ÜBEN'}${a.assisted?' · MIT HINWEIS':''} · ${lessonById[q.lesson].title}</div><h3>${esc(q.prompt)}</h3><p class="help" style="margin-top:12px">Deine Antwort: ${esc(a.value===''?'Keine Antwort':q.type==='choice'?q.options[a.value]:a.value)}</p><div class="feedback ${a.correct?'':'error'}"><strong>${esc(answerLabel(q))}</strong>${esc(q.explanation)}${a.counter?`<p>${esc(a.counter)}</p>`:''}</div><a class="back-link" style="margin:12px 0 0" href="#lesson/${q.lesson}">Erklärung ansehen ${icon('arrow')}</a></section>`;}).join('')}</div>`,'review');
}
function symbolKeyboard(target,symbols){return `<div class="symbol-keyboard" aria-label="Mathematische Zeichen einfügen">${symbols.map(s=>`<button type="button" data-action="symbol" data-target="${target}" data-symbol="${esc(s)}" aria-label="${esc(s)} einfügen">${esc(s)}</button>`).join('')}</div>`;}

const labs=[['sets','layers','Sprachen'],['regex','code','RegEx'],['dfa','nodes','DEA-Lauf'],['builder','flask','DEA bauen'],['complexity','chart','Wachstum']];
function labPage(id){if(!labs.some(l=>l[0]===id))return notFound();return shell(`${pageHead('DEIN ÜBUNGSLABOR','Hier wird Theorie greifbar.','Verändere etwas. Beobachte das Ergebnis. Verstehe den Zusammenhang.')}<nav class="lab-tabs" aria-label="Lernlabore">${labs.map(([key,i,t])=>`<a href="#lab/${key}" class="${key===id?'active':''}" ${key===id?'aria-current="page"':''}>${icon(i)}${t}</a>`).join('')}</nav>${{sets:setLab,regex:regexLab,dfa:dfaLab,builder:builderLab,complexity:complexityLab}[id]()}`,'lab');}
function setLab(){return `<div class="lab-grid"><section class="card"><h2>Mit Sprachen rechnen</h2><p class="help" style="margin-bottom:20px">Gib endliche Sprachen ein. Rechne erst selbst, dann lass dir die Entstehung zeigen.</p><label class="field">Sprache A<input id="set-a" value="{ε, 0}" maxlength="1000" autocomplete="off" spellcheck="false"></label><label class="field">Sprache B<input id="set-b" value="{1, 01}" maxlength="1000" autocomplete="off" spellcheck="false"></label><label class="field">Operation<select id="set-op"><option value="concat">A · B · Konkatenation</option><option value="union">A ∪ B · Vereinigung</option><option value="intersection">A ∩ B · Schnitt</option><option value="difference">A ∖ B · Differenz</option><option value="quotient">A / B · Rechtsquotient</option></select></label><label class="field">Dein vermutetes Ergebnis<input id="set-answer" placeholder="Zum Beispiel: {ε, 0, 01}" maxlength="1000" autocomplete="off" spellcheck="false"></label>${symbolKeyboard('set-answer',['ε','∅','{','}',','])}<div class="inline-actions"><button class="btn" data-action="set-check">Ergebnis prüfen</button><button class="btn ghost" data-action="set-solve">Herleitung zeigen</button></div></section><section class="card"><h2>Jedes Wort hat einen Weg.</h2><div id="set-output" role="status"><p class="muted small">Bei der Konkatenation entsteht aus jedem Paar ein Wort. Manche Paare liefern dasselbe Ergebnis – in der Ergebnismenge zählt es nur einmal.</p><div class="example"><h3>Ein Denkimpuls</h3><p>Wenn du ε mit 01 verkettest und 0 mit 1, was fällt dir auf?</p></div></div><div class="separator"></div><p class="help">A / B entfernt passende vollständige Endstücke aus B. Ein Komplement relativ zu Σ* kann unendlich sein und wird deshalb nicht als endliche Liste berechnet.</p><a href="#lesson/quotient" class="back-link" style="margin-top:14px">Rechtsquotient verstehen ${icon('arrow')}</a></section></div>`;}
function runSetLab(check){
  const output=document.querySelector('#set-output');
  try{
    const a=parseSet(document.querySelector('#set-a').value),b=parseSet(document.querySelector('#set-b').value),op=document.querySelector('#set-op').value,result=languageOperation(a,b,op);
    let feedback='';if(check){const guessed=parseSet(document.querySelector('#set-answer').value),ok=equalSets(guessed,result);feedback=`<div class="feedback ${ok?'':'error'}"><strong>${ok?'Genau richtig.':'Vergleiche deine Menge mit der Herleitung.'}</strong>${ok?'Du hast alle Ergebniswörter gefunden.':'Prüfe Reihenfolge, doppelte Ergebnisse und das leere Wort.'}</div>`;}
    let pairs=[];
    if(op==='concat')pairs=a.flatMap(x=>b.map(y=>`${wordLabel(x)} · ${wordLabel(y)} = ${wordLabel(x+y)}`));
    else if(op==='quotient')pairs=a.flatMap(x=>b.filter(y=>x.endsWith(y)).map(y=>`${wordLabel(x)} ohne Suffix ${wordLabel(y)} → ${wordLabel(y?x.slice(0,-y.length):x)}`));
    else pairs=result.map(w=>`${wordLabel(w)}: ${a.includes(w)?'in A':'nicht in A'}, ${b.includes(w)?'in B':'nicht in B'}`);
    output.innerHTML=`${feedback}<div class="eyebrow" style="margin-top:20px">DEIN ERGEBNIS</div><div class="set-result">${esc(setLabel(result.slice(0,80)))}</div><p class="help">${result.length} verschiedene Wörter.${result.length>80?' Angezeigt werden die ersten 80.':''}${op==='concat'?` ${a.length*b.length} Paare wurden gebildet.`:''}</p><div class="separator"></div><h3>So entsteht die Menge</h3><div class="pair-list">${pairs.length?pairs.slice(0,40).map(p=>esc(p)).join('<br>'):'Kein passendes Paar bzw. Wort. Deshalb ist das Ergebnis ∅.'}${pairs.length>40?'<br>… weitere Schritte nicht angezeigt.':''}</div><p class="help" style="margin-top:18px">Freies Experimentieren vergibt keine XP. Die Lektionsaufgaben liefern deinen Lernnachweis.</p>`;
  }catch(e){output.innerHTML=`<div class="feedback error">${esc(e.message)}</div>`;}
}
const regexTasks=[{id:'end01',title:'Endet auf 01',answer:'(0|1)*01'},{id:'two',title:'Genau zwei Einsen',answer:'0*10*10*'},{id:'none',title:'Keine Eins',answer:'0*'},{id:'len3',title:'Genau Länge 3',answer:'(0|1)(0|1)(0|1)'},{id:'even',title:'Gerade Anzahl Einsen',answer:'0*(10*10*)*'},{id:'penult0',title:'Vorletztes Zeichen 0',answer:'(0|1)*0(0|1)'}];
function regexLab(){return `<div class="lab-grid"><section class="card"><h2>Dein Muster, deine Sprache</h2><p class="help" style="margin-bottom:20px">Alphabet: {0,1}. Erlaubt sind ε, ∅, Vereinigung (∪ oder |), Verkettung, *, + und Klammern.</p><label class="field">Konstruktionsaufgabe<select id="regex-task">${regexTasks.map(t=>`<option value="${t.id}">${t.title}</option>`).join('')}</select></label><label class="field">Dein regulärer Ausdruck<input id="regex-expression" value="(0|1)*1" maxlength="120" spellcheck="false" autocomplete="off"></label>${symbolKeyboard('regex-expression',['0','1','ε','∅','∪','(',')','*','+'])}<label class="field">Zusätzlich ein Wort testen (leer lassen für ε)<input id="regex-word" value="101" maxlength="50" spellcheck="false" autocomplete="off" inputmode="numeric"></label><div class="inline-actions"><button class="btn" data-action="regex-check">Aufgabe prüfen</button><button class="btn secondary" data-action="regex-preview">Wörter ausprobieren</button></div><p class="help" style="margin-top:20px">Jede Aufgabe akzeptiert auch anders geschriebene, gleichwertige Ausdrücke. Ein vollständiger Vergleich liefert bei Abweichung ein kürzestes Gegenbeispiel.</p></section><section class="card"><h2>Was akzeptiert dein Ausdruck?</h2><div id="regex-output" role="status"><p class="small muted">Starte mit dem Beispielausdruck und teste ihn. Passt er bereits zur Aufgabe „endet auf 01“?</p><div class="example"><h3>Genau hinsehen</h3><p>Ein RegEx beschreibt hier immer das ganze Wort. Eine passende Teilzeichenfolge allein reicht nicht.</p></div></div></section></div>`;}
function runRegexLab(check){
  const output=document.querySelector('#regex-output');
  try{
    const expr=document.querySelector('#regex-expression').value,matcher=compileRegex(expr),word=document.querySelector('#regex-word').value.trim();
    if(/[^01]/.test(word))throw new Error('Das Testwort darf nur 0 und 1 enthalten. Für ε lass das Feld leer.');
    const task=regexTasks.find(t=>t.id===document.querySelector('#regex-task').value);let result='';
    if(check){const comp=compareRegex(expr,task.answer);result=`<div class="feedback ${comp.equal?'':'error'}"><strong>${comp.equal?'Die Sprache stimmt vollständig überein.':'Ein Gegenbeispiel zeigt den Unterschied.'}</strong>${comp.equal?`Dein Ausdruck erfüllt „${task.title}“. Der vollständige Vergleich ist erfolgreich.`:`${wordLabel(comp.word)} wird von deinem Ausdruck ${comp.actual?'akzeptiert':'abgelehnt'}, müsste für „${task.title}“ aber ${comp.expected?'akzeptiert':'abgelehnt'} werden.`}</div>`;}
    const accepted=matcher.test(word);output.innerHTML=`${result}<p style="margin:20px 0"><span class="chip ${accepted?'accept':'reject'}">${esc(wordLabel(word))}</span> <span class="small">${accepted?'wird akzeptiert':'wird abgelehnt'}</span></p><h3>Alle Binärwörter bis Länge 3</h3><div class="chips" style="margin-top:15px">${binaryWords(3).map(w=>`<span class="chip ${matcher.test(w)?'accept':'reject'}" title="${matcher.test(w)?'Akzeptiert':'Abgelehnt'}">${wordLabel(w)}</span>`).join('')}</div><p class="help" style="margin-top:20px">Grün: akzeptiert. Rot: abgelehnt. Diese Vorschau ist endlich und allein kein Beweis. „Aufgabe prüfen“ vergleicht die vollständigen Sprachen.</p>`;
  }catch(e){output.innerHTML=`<div class="feedback error">${esc(e.message)}</div>`;}
}
function currentDfa(){const m=machines[dfaKey];return {...m,accept:dfaComplement?m.states.filter(s=>!m.accept.includes(s)):m.accept};}
function dfaLab(){return `<section class="card"><div class="lab-grid"><div><h2>Schritt für Schritt durch den Automaten</h2><label class="field" style="margin-top:20px">Beispielautomat<select id="dfa-machine">${Object.entries(machines).map(([key,m])=>`<option value="${key}" ${key===dfaKey?'selected':''}>${m.name}</option>`).join('')}</select></label><label class="field">Eingabewort (leer für ε)<input id="dfa-word" value="${esc(dfaWord)}" maxlength="40" spellcheck="false" inputmode="numeric"></label><label class="check-line"><input type="checkbox" id="dfa-complement" ${dfaComplement?'checked':''}> Komplement bilden: Endzustände umkehren</label><div class="inline-actions"><button class="btn" data-action="dfa-start">Wort laden</button><button class="btn secondary" data-action="dfa-step">Ein Schritt ${icon('arrow')}</button><button class="btn ghost" data-action="dfa-all">Bis zum Ende</button></div></div><div><div class="eyebrow">SO LIEST DU DIE ANZEIGE</div><p class="small muted">Die helle Markierung ist der aktuelle Zustand, ein Doppelkreis kennzeichnet akzeptierende Zustände. Die vollständige Übergangstabelle zeigt, wohin jedes Zeichen führt.</p><div class="callout" style="margin-top:20px"><strong>Erst am Ende entscheiden</strong>Akzeptanz wird nach dem vollständigen Wort geprüft. Bei ε bleibt der Automat im Startzustand.</div></div></div><div id="dfa-stage" aria-live="polite"></div></section>`;}
function renderDfaStage(){
  const target=document.querySelector('#dfa-stage');if(!target)return;
  try{
    const m=currentDfa(),run=runDfa(m,dfaWord),pos=Math.min(dfaPosition,dfaWord.length),cur=run.trace[pos],done=pos===dfaWord.length;
    target.innerHTML=`<div class="dfa-states" role="img" aria-label="Aktueller Zustand ${cur}. Akzeptierende Zustände ${m.accept.join(', ')}">${m.states.map(s=>`<div class="dfa-state ${s===cur?'active':''} ${m.accept.includes(s)?'accepting':''}">${s}<span class="state-name">${s===m.start?'Start':''}</span></div>`).join('')}</div><div class="word-tape" aria-label="Eingabewort, ${pos} von ${dfaWord.length} Zeichen gelesen">${dfaWord?[...dfaWord].map((c,i)=>`<span class="${i<pos?'read':i===pos?'next':''}">${c}</span>`).join(''):'<span>ε</span>'}</div><p class="small">${done?`Eingabe vollständig · ${m.accept.includes(cur)?'<strong class="lime">Akzeptiert</strong>':'<strong style="color:var(--red)">Abgelehnt</strong>'}`:`Schritt ${pos} von ${dfaWord.length} · nächstes Zeichen: <strong>${dfaWord[pos]}</strong>`}</p><div class="trace">${run.trace.slice(0,pos+1).map(esc).join(' → ')}</div><div class="table-scroll"><table><caption class="help" style="text-align:left">Vollständige Übergangsfunktion · Start: ${m.start} · F = ${esc(setLabel(m.accept))}</caption><thead><tr><th>Zustand</th><th>Bei 0</th><th>Bei 1</th><th>Bedeutung im Original</th></tr></thead><tbody>${m.states.map(s=>`<tr class="${s===cur?'current-row':''}"><td>${s===m.start?'→ ':''}${m.accept.includes(s)?'* ':''}${s}</td><td>${m.transitions[s][0]}</td><td>${m.transitions[s][1]}</td><td>${m.meanings[s]}</td></tr>`).join('')}</tbody></table></div>`;
  }catch(e){target.innerHTML=`<div class="feedback error">${esc(e.message)}</div>`;}
}
function emptyBuilder(){const m=machines[builderKey];builderDraft={accept:[],transitions:Object.fromEntries(m.states.map(s=>[s,{'0':'','1':''}]))};}
function builderLab(){
  const m=machines[builderKey];if(!builderDraft.transitions?.[m.start]||Object.keys(builderDraft.transitions).length!==m.states.length)emptyBuilder();
  return `<section class="card"><div class="lab-grid"><div><h2>Dein Automat. Deine Übergänge.</h2><label class="field" style="margin-top:20px">Konstruktionsaufgabe<select id="builder-task">${['ends1','alternate','contains1','parity'].map(key=>`<option value="${key}" ${key===builderKey?'selected':''}>${machines[key].name}${['ends1','alternate'].includes(key)?' · Wochenziel':''}</option>`).join('')}</select></label><div class="builder-task"><strong>${m.description}</strong><p>Alphabet {0,1} · Startzustand ${m.start} · ${m.states.length} vorgegebene Zustände. Fülle jeden Übergang aus und wähle alle akzeptierenden Zustände.</p></div><p class="help">Andere korrekte Zustandszuordnungen werden anerkannt. Die Prüfung vergleicht die vollständige Sprache. Ein Gegenbeispiel zeigt dir bei Fehlern, welches Wort anders behandelt wird.</p></div><div><div class="eyebrow">SO BAUST DU EINEN DEA</div><p class="small muted">01 · Welche Information musst du merken?<br>02 · Was bedeutet jeder Zustand?<br>03 · Wie verändert 0 oder 1 diese Information?<br>04 · Welche Zustände erfüllen die Bedingung?</p><button class="btn ghost" data-action="builder-help" style="margin-top:20px" ${builderHelp?'disabled':''}>Zustandsideen als Hinweis</button>${builderHelp?`<div class="feedback info"><strong>Mit Unterstützung üben</strong>${m.states.map(s=>`${s}: ${m.meanings[s]}`).join('<br>')}<p>Dieser Versuch zählt nicht für den Pokal „ohne Vorlage“.</p></div>`:''}</div></div><div class="table-scroll"><table><thead><tr><th>Zustand</th><th>Bei 0 nach …</th><th>Bei 1 nach …</th><th>Akzeptiert?</th></tr></thead><tbody>${m.states.map(s=>`<tr><td>${s===m.start?'→ ':''}${s}</td>${['0','1'].map(c=>`<td><select aria-label="Übergang ${s} bei ${c}" data-builder-state="${s}" data-builder-char="${c}"><option value="">Wählen</option>${m.states.map(t=>`<option value="${t}" ${builderDraft.transitions[s][c]===t?'selected':''}>${t}</option>`).join('')}</select></td>`).join('')}<td><label class="check-line" style="margin:0"><input type="checkbox" data-builder-accept="${s}" ${builderDraft.accept.includes(s)?'checked':''} aria-label="${s} akzeptierend"><span>Ja</span></label></td></tr>`).join('')}</tbody></table></div><div class="inline-actions" style="margin-top:24px"><button class="btn" data-action="builder-check">Automat prüfen ${icon('check')}</button><button class="btn ghost" data-action="builder-reset">Ohne Vorlage neu beginnen</button></div><div id="builder-output" role="status"></div>${state.builders[builderKey]?'<p class="completed-stamp" style="margin-top:20px">✓ Diese Konstruktion wurde bereits ohne Vorlage gelöst.</p>':''}</section>`;
}
function checkBuilder(){const out=document.querySelector('#builder-output');try{const m=machines[builderKey],candidate={...m,accept:builderDraft.accept,transitions:builderDraft.transitions};const result=compareDfa(candidate,m);if(result.equal){if(!builderHelp){announceBadges(completeBuilder(state,builderKey));persist();}out.innerHTML=`<div class="feedback"><strong>Dein Automat erkennt genau die verlangte Sprache.</strong>Alle erreichbaren Zustandskombinationen wurden verglichen. ${builderHelp?'Gut mit Unterstützung geübt. Beginne später ohne Vorlage neu, um den Nachweis zu erbringen.':'Dein selbstständiger Konstruktionsnachweis ist gespeichert.'}</div>`;}else{const actual=runDfa(candidate,result.word);out.innerHTML=`<div class="feedback error"><strong>Gegenbeispiel: ${esc(wordLabel(result.word))}</strong>Dein Automat ${result.actual?'akzeptiert':'verwirft'} dieses Wort. Die Aufgabe verlangt, es ${result.expected?'anzunehmen':'abzulehnen'}.<p>Dein Lauf: ${actual.trace.join(' → ')}.</p><p>Prüfe die Zustandsbedeutung und die Übergänge auf diesem Weg.</p></div>`;}}catch(e){out.innerHTML=`<div class="feedback error">${esc(e.message)}</div>`;}}
function complexityLab(){return `<div class="lab-grid"><section class="card"><h2>Ein kleines n macht einen großen Unterschied.</h2><p class="small muted" style="margin-top:15px">Bewege den Regler und vergleiche beispielhafte exakte Schrittzahlen. Die Balken sind logarithmisch skaliert, damit auch große Unterschiede sichtbar bleiben.</p><label class="field" style="margin-top:27px">Eingabegröße n: <strong id="growth-n" class="lime">10</strong><input type="range" id="growth-slider" min="1" max="30" value="10" aria-label="Eingabegröße n"></label><div id="growth-chart" role="status"></div><p class="help" style="margin-top:24px">Die Werte n, n², n³ und 2ⁿ sind hier konkrete Modellfunktionen. O(n²) selbst bezeichnet eine Klasse oberer Schranken, keine genaue Schrittzahl.</p></section><section class="card"><h2>Was passiert beim Verzehnfachen?</h2><div class="table-scroll"><table><thead><tr><th>Wachstum</th><th>Faktor bei n → 10n</th></tr></thead><tbody><tr><td>n</td><td>10</td></tr><tr><td>n²</td><td>100</td></tr><tr><td>n³</td><td>1.000</td></tr><tr><td>2ⁿ</td><td>2⁹ⁿ, abhängig von n</td></tr></tbody></table></div><div class="callout" style="margin-top:24px"><strong>Die wichtige Trennung</strong>Die Chomsky-Hierarchie ordnet Sprachklassen und Modelle. Eine O-Laufzeit lässt sich daraus nicht pauschal pro Zeile ablesen.</div><a href="#lesson/complexity" class="back-link" style="margin-top:20px">Die Grundlagen lesen ${icon('arrow')}</a></section></div>`;}
function renderGrowth(){const n=Number(document.querySelector('#growth-slider')?.value||10);const vals=[['n',n],['n²',n*n],['n³',n*n*n],['2ⁿ',2**n]];document.querySelector('#growth-n').textContent=n;document.querySelector('#growth-chart').innerHTML=vals.map(([name,value])=>`<div class="chart-row"><strong>${name}</strong><div class="chart-bar"><span style="width:${Math.max(1,Math.log2(value+1)/30*100)}%"></span></div><span class="number">${value.toLocaleString('de-DE')}</span></div>`).join('');}

let pendingImport=null;
function exportProgress(){
  const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`orbit-fortschritt-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Deine Sicherungsdatei wurde zum Download vorbereitet.');
}
function updateFocusDisplay(){
  const t=document.querySelector('#focus-timer'),b=document.querySelector('#focus-toggle');if(t)t.textContent=formatTime(focus.remaining);if(b)b.innerHTML=icon(focus.running?'pause':'play')+(focus.running?'Pausieren':'Fokus starten');
}
app.addEventListener('click',async event=>{
  const button=event.target.closest('[data-action]');if(!button||button.disabled)return;event.preventDefault();
  const action=button.dataset.action,id=button.dataset.id;
  try{
    switch(action){
      case 'week':selectedWeek=Number(button.dataset.week);render();break;
      case 'daily':dailySession();break;
      case 'review':startSession(dueQuestions(state).slice(0,15),{type:'review',title:'Deine fälligen Wiederholungen'});break;
      case 'retry-question':startSession([questionById[id]],{type:'review',title:'Aus einem Fehler lernen'});break;
      case 'lesson-quiz':startSession(shuffled(questions.filter(q=>q.lesson===id)),{type:'lesson',lesson:id,title:lessonById[id].title});break;
      case 'weekly-check':startSession(checkQuestions,{type:'check',title:'Wochencheck · Woche 1'});break;
      case 'select-answer':session.selected=Number(button.dataset.index);render();break;
      case 'submit-answer':submitAnswer();break;
      case 'skip':submitAnswer(true);break;
      case 'next-question':nextQuestion();break;
      case 'hint':session.input=document.querySelector('#quiz-input')?.value||'';session.hint=true;render();break;
      case 'save-note':state.notes[id]=document.querySelector('#lesson-note').value;if(persist())document.querySelector('#note-status').textContent='Deine Erklärung ist auf diesem Gerät gespeichert.';break;
      case 'save-error':state.errors[id].note=document.querySelector(`#error-note-${id}`).value;state.errors[id].rule=document.querySelector(`#error-rule-${id}`).value;if(persist())toast('Deine Fehlernotiz ist gespeichert.');break;
      case 'symbol':{const input=document.getElementById(button.dataset.target);if(input.disabled)break;const start=input.selectionStart??input.value.length,end=input.selectionEnd??start;input.setRangeText(button.dataset.symbol,start,end,'end');input.dispatchEvent(new Event('input',{bubbles:true}));input.focus();break;}
      case 'set-check':runSetLab(true);break;
      case 'set-solve':runSetLab(false);break;
      case 'regex-check':runRegexLab(true);break;
      case 'regex-preview':runRegexLab(false);break;
      case 'dfa-start':{const word=document.querySelector('#dfa-word').value.trim();if(/[^01]/.test(word)){document.querySelector('#dfa-stage').innerHTML='<div class="feedback error">Nur 0 und 1 sind erlaubt. Für ε lass das Feld leer.</div>';break;}dfaWord=word;dfaPosition=0;renderDfaStage();break;}
      case 'dfa-step':dfaPosition=Math.min(dfaPosition+1,dfaWord.length);renderDfaStage();break;
      case 'dfa-all':dfaPosition=dfaWord.length;renderDfaStage();break;
      case 'open-builder':builderKey=id;builderHelp=false;emptyBuilder();go('lab/builder');break;
      case 'builder-help':builderHelp=true;render();break;
      case 'builder-reset':builderHelp=false;emptyBuilder();render();break;
      case 'builder-check':checkBuilder();break;
      case 'focus':if(focus.remaining===0)focus.remaining=25*60;focus.running=!focus.running;focus.last=Date.now();updateFocusDisplay();break;
      case 'focus-reset':focus={remaining:25*60,running:false,last:Date.now(),unsaved:0};persist();updateFocusDisplay();break;
      case 'save-settings':{const value=document.querySelector('#exam-date').value;if(!/^\d{4}-\d{2}-\d{2}$/.test(value)||value<'2020-01-01'||value>'2100-12-31')throw new Error('Wähle ein gültiges Datum zwischen 2020 und 2100.');state.goal=Number(document.querySelector('#goal').value);state.examDate=value;if(persist()){render();toast('Deine Lernziele sind gespeichert.');}break;}
      case 'export':exportProgress();break;
      case 'import':document.querySelector('#import-file').click();break;
      case 'cancel-import':pendingImport=null;document.querySelector('#import-preview').innerHTML='';break;
      case 'confirm-import':if(pendingImport){state=pendingImport;pendingImport=null;session=null;storageBlocked=false;storageNotice=null;persist();render();toast('Die Sicherung wurde übernommen.');}break;
      case 'reset':if(confirm('Deinen gesamten Orbit-Lernstand auf diesem Gerät zurücksetzen? Exportiere vorher eine Sicherung, wenn du ihn behalten möchtest.')){state=blankState();session=null;storageBlocked=false;storageNotice=null;focus={remaining:1500,running:false,last:Date.now(),unsaved:0};persist();render();toast('Dein Lernraum ist bereit für einen Neustart.');}break;
      case 'recover':if(confirm('Den unlesbaren Speicherstand nach eigener Sicherung durch den aktuell angezeigten Stand ersetzen?')){storageBlocked=false;storageNotice=null;persist();render();}break;
      case 'install':if(installPrompt){await installPrompt.prompt();installPrompt=null;render();}break;
    }
  }catch(e){toast(e.message||'Das hat gerade nicht geklappt. Bitte versuche es erneut.');}
});
app.addEventListener('change',async event=>{
  const el=event.target;
  if(el.id==='dfa-machine'){dfaKey=el.value;dfaPosition=0;renderDfaStage();}
  if(el.id==='dfa-complement'){dfaComplement=el.checked;renderDfaStage();}
  if(el.id==='builder-task'){builderKey=el.value;builderHelp=false;emptyBuilder();render();}
  if(el.dataset.builderState)builderDraft.transitions[el.dataset.builderState][el.dataset.builderChar]=el.value;
  if(el.dataset.builderAccept){const s=el.dataset.builderAccept;builderDraft.accept=el.checked?[...new Set([...builderDraft.accept,s])]:builderDraft.accept.filter(x=>x!==s);}
  if(el.id==='import-file'){
    const file=el.files?.[0];if(!file)return;
    try{if(file.size>2*1024*1024)throw new Error('Diese Sicherung ist zu groß (maximal 2 MB).');pendingImport=validateImport(JSON.parse(await file.text()));const imported=stats(pendingImport);document.querySelector('#import-preview').innerHTML=`<div class="feedback info"><strong>Sicherung erkannt: ${imported.completed} Lektionen, ${imported.xp} XP</strong>Aktueller Stand: ${stats(state).completed} Lektionen, ${stats(state).xp} XP.<p>Beim Übernehmen wird dein aktueller Stand ersetzt.</p><div class="inline-actions" style="margin-top:15px"><button class="btn" data-action="confirm-import">Sicherung übernehmen</button><button class="btn ghost" data-action="cancel-import">Abbrechen</button></div></div>`;}catch(e){pendingImport=null;document.querySelector('#import-preview').innerHTML=`<div class="feedback error">${esc(e instanceof SyntaxError?'Die Datei enthält kein gültiges JSON. Dein Stand bleibt erhalten.':e.message)}</div>`;}el.value='';
  }
});
app.addEventListener('input',event=>{if(event.target.id==='growth-slider')renderGrowth();if(event.target.id==='quiz-input'&&session)session.input=event.target.value;});
app.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.id==='quiz-input'){event.preventDefault();submitAnswer();}});
setInterval(()=>{
  const now=Date.now();if(!focus.running||document.hidden){focus.last=now;return;}
  const seconds=Math.min(3,Math.floor((now-focus.last)/1000));if(seconds<=0)return;focus.last=now;
  const counted=Math.min(seconds,focus.remaining);focus.remaining-=counted;state.focusSeconds+=counted;focus.unsaved+=counted;
  if(focus.unsaved>=15){persist();focus.unsaved=0;}
  if(focus.remaining===0){focus.running=false;persist();toast('25 Minuten geschafft. Zeit für eine kurze Pause.');}
  updateFocusDisplay();
},1000);
document.addEventListener('visibilitychange',()=>{focus.last=Date.now();if(document.hidden&&focus.unsaved){persist();focus.unsaved=0;}});
window.addEventListener('pagehide',()=>{if(focus.unsaved)persist();});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});document.querySelector('#content')?.focus({preventScroll:true});});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
render();
